"""Publish diagnostic reports only; no application source/config changes."""
from pathlib import Path
import sys,json,hashlib,numpy as np
r=Path(sys.argv[1]);a=json.loads((r/'analysis/comparison.json').read_text());audit=json.loads((r/'input_audit.json').read_text());timing=json.loads((r/'source_timing.json').read_text());result=a['replay_result'];h=a['health'];checks=a['distance_and_return_checks'];overall=a['overall_return_check'];source=Path(audit['source_bag']);sha=hashlib.sha256()
with source.open('rb') as f:
 for block in iter(lambda:f.read(8*1024*1024),b''):sha.update(block)
(r/'source.sha256').write_text(sha.hexdigest()+'  '+str(source)+'\n')
# Reproduce only the saved 20 ms TF emission selection to inspect the end boundary.
s=np.load(r/'source_decoded.npz');lasttf=None
for stamp in s['vendor_stamp_ns']:
 if lasttf is None or int(stamp)-lasttf>=20_000_000:lasttf=int(stamp)
o=np.load(r/'outputs.npz');missing=np.setdiff1d(o['odom_stamp_ns'],o['map_odom_stamp_ns']);tfcheck={'missing_pose_count':len(missing),'missing_only_at_end':bool(len(missing)>0 and np.array_equal(missing,o['odom_stamp_ns'][-len(missing):])),'all_earlier_pose_tf_sequences_exact':bool(np.array_equal(o['odom_stamp_ns'][:-len(missing)] if len(missing) else o['odom_stamp_ns'],o['map_odom_stamp_ns'])),'last_pose_beyond_last_derived_vendor_tf_ms':float((int(o['odom_stamp_ns'][-1])-lasttf)/1e6)};(r/'tf_boundary_check.json').write_text(json.dumps(tfcheck,indent=2)+'\n')
name=source.parent.name
lines=[f'# {name} bag: Point-LIO and vendor odometry','',f'Source: `{source}`. Duration **{audit["duration_s"]:.3f} s**, {audit["messages"]:,} messages.','', 'Operator confirmed the same route as classic: 3 m forward, wait, 3 m back, wait; then 5 m forward, wait, 5 m back, wait.','', '| Check | Point-LIO | Vendor odometry |','|---|---:|---:|']
for c in checks:
 target=c['nominal_distance_m'];l,v=c['point_lio'],c['vendor']
 lines += [f"| {target:g} m outbound horizontal displacement | {l['outbound_horizontal_endpoint_distance_m']:.4f} m | {v['outbound_horizontal_endpoint_distance_m']:.4f} m |",f"| {target:g} m inbound horizontal displacement | {l['inbound_horizontal_endpoint_distance_m']:.4f} m | {v['inbound_horizontal_endpoint_distance_m']:.4f} m |",f"| {target:g} m leg return offset | {100*l['return_horizontal_offset_m']:.2f} cm | {100*v['return_horizontal_offset_m']:.2f} cm |"]
lines += [f"| Final offset from original start, horizontal | {100*overall['point_lio']['final_horizontal_offset_from_original_start_m']:.2f} cm | {100*overall['vendor']['final_horizontal_offset_from_original_start_m']:.2f} cm |",f"| Final height change from original start | {100*overall['point_lio']['final_vertical_offset_from_original_start_m']:.2f} cm | {100*overall['vendor']['final_vertical_offset_from_original_start_m']:.2f} cm |",'','![Comparison plot](analysis/comparison.png)','','## Recording integrity','',f"All **{audit['chunks']:,} zstd chunks decompress**. Full container traversal, MCAP statistics and metadata message counts agree. Summary CRC matches. No chunk payload CRCs are present, so this is not a per-payload CRC guarantee. All mapping inputs were deserialized. Unrelated message schemas were not fully validated.",'',f"Approved raw/body conversion agrees across {audit['geometry_matches']:,} matched points in {audit['geometry_pairs']} scans, maximum residual {audit['geometry_max_residual_m']*1e6:.3f} micrometres. This validates the recorded topic conversion, not a surveyed mount.",'','Source MCAP was read-only; source.sha256 identifies it. Original Jazzy metadata was preserved. Separate Humble-compatible SQLite replay includes only raw cloud, calibrated body IMU, vendor odometry and derived clock/TF. No robot command topics replayed.','','## Recomputed Point-LIO','',f"No Point-LIO output is present in the source. This replay uses the existing binary, unchanged bias calibration/extrinsics, zero acquisition-lag correction and the same temporary **init_map_size=4000** setting as classic. Headless, 0.5x playback, isolated localhost-only DDS domain 209. Application hashes unchanged: **{result['application_unchanged']}**.",'',f"Observer cloud delivery matched all {result['input_cloud_messages']:,} source stamps exactly: **{result['cloud_delivery_exact']}**. Calibrated IMU delivery matched all {result['input_imu_messages']:,} stamps exactly: **{result['imu_delivery_exact']}**. Duplicate SportModeState samples dropped: {audit['calibrated_imu_duplicates_dropped']}; converter errors: {audit['body_converter_errors']}.",'',f"Stop reason `{result['stop_reason']}`, player exit {result['player_returncode']}, launch exit {result['launch_returncode']}. Point-LIO: **{h['lio_poses']:,} poses at {h['average_pose_frequency_hz']:.3f} Hz**. Nonfinite pose values {h['nonfinite_pose_values']}; nonincreasing stamps {h['nonincreasing_pose_stamps']}. Largest single translation step {h['lio_step_translation_m']['max']*100:.2f} cm, rotation {h['lio_step_rotation_deg']['max']:.2f} degrees. Steps >15 cm: {h['steps_over_0_15_m']}; rotations >5 degrees: {h['rotation_steps_over_5_deg']}.",'',f"TF parent conflicts: {result['multiple_tf_parents']}. Missing pose TF stamps {h['tf_missing_pose_stamp_count']}; extra stamps {h['tf_extra_stamp_count']}; exact full sequence match {h['tf_pose_stamps_exact']}. End-boundary check: `{json.dumps(tfcheck)}`. Deferred exact-time lookup retries are distinct from dropped outputs; selected endpoint holds precede the recording boundary.",'','## Timing and endpoint selection','',f"Raw cloud median period {timing['raw']['positive_dt_median_p95_p99_max_s'][0]*1000:.3f} ms, no duplicate/backward stamps, no gaps exceeding three median periods. Calibrated IMU: {timing['imu']['backwards']} backwards stamps, {timing['imu']['source_gaps_over_3_median_count']} gaps exceeding three median periods, maximum {timing['imu']['positive_dt_median_p95_p99_max_s'][-1]*1000:.3f} ms. Gaps are retained, not filled. Detailed largest gaps and nearby pose steps appear in comparison.json.",'',f"IMU recording brackets {timing['scans_imu_bracketed']['within_recording']} scans; {timing['scans_imu_bracketed']['outside_recording']} scans extend outside its boundaries. Point-LIO first output {h['first_pose_s']:.3f} s after first raw cloud header.",'','Recorder minus source-header time includes a host/robot clock offset; it is not direct network latency. Header times are unchanged. Zero acquisition lag remains uncalibrated; replay success does not establish exact LiDAR/IMU acquisition synchronization.','', 'Endpoint holds were selected independently for this recording from its quiet waits. All times are seconds after the first raw-cloud header. Values are median positions; both estimates refer to the IMU using the developer body-to-IMU lever arm. No scale fit or per-leg pose alignment was used.','']
for name,hold in a['holds'].items():lines += [f"- {name}: {hold['time_window_s'][0]:g}–{hold['time_window_s'][1]:g} s, {hold['point_lio_samples']} poses; Point-LIO p95 distance to median {hold['lio_position_p95_distance_to_median_m']*100:.2f} cm, body gyro RMS {hold['body_gyro_rms_rad_s']:.4f} rad/s."]
lines += ['','## Vertical consistency','']
for c in checks:
 lines += [f"- {c['nominal_distance_m']:g} m leg: Point-LIO far-hold height change {100*c['point_lio']['outbound_vertical_change_m']:.2f} cm; returned height change {100*c['point_lio']['return_vertical_offset_m']:.2f} cm."]
for f in a['revisited_start_floor_checks']:
 if f['common_15cm_xy_cells']:lines += [f"- {f['hold']}: {f['common_15cm_xy_cells']} common 15 cm floor-candidate cells; median absolute difference {1000*f['median_absolute_floor_height_difference_m']:.2f} mm, p90 {1000*f['p90_absolute_floor_height_difference_m']:.2f} mm."]
lines += ['',a['floor_method'],'','An outward height slope that reverses on return can include actual floor slope or gravity/map tilt. Return-height and repeated-cell agreement measure consistency, not absolute vertical accuracy.','','## Limits','']+['- '+s for s in a['measurement_limitations']]+['','Quiet-hold pose variation is included above. Small median return offsets must not be interpreted as an equally precise absolute accuracy guarantee.','', 'Details: [comparison.json](analysis/comparison.json), [input_audit.json](input_audit.json), [source_timing.json](source_timing.json), [result.json](result.json).']
extra=r/'analysis/default_extra_movement.json'
if extra.exists():
 e=json.loads(extra.read_text());first=e['brief_first_stop'];supp=['','## Extra movement after the main return','',f"The default recording includes renewed SportModeState speed and gyro motion around 76–78 s, after a brief initial stop. At 74.8–75.8 s, the Point-LIO median was {100*first['point_lio']['horizontal_offset_from_original_start_m']:.2f} cm from the original start, versus vendor {100*first['vendor']['horizontal_offset_from_original_start_m']:.2f} cm. Point-LIO estimates a subsequent {100*e['point_lio_shift_between_these_stops_m']:.2f} cm shift before the final quiet hold. The main table deliberately retains the final quiet hold; its 14 cm Point-LIO offset must not all be labelled drift. The earlier stop is brief and has more body sway. Details: [default_extra_movement.json](analysis/default_extra_movement.json)."]
 lines += supp
(r/'REPORT.md').write_text('\n'.join(lines)+'\n');print(r/'REPORT.md')
